package org.xianshen.mumirrorb.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.xianshen.mumirrorb.common.exception.BusinessException;
import org.xianshen.mumirrorb.config.GrowthProperties;
import org.xianshen.mumirrorb.mapper.GrowthAxisMapper;
import org.xianshen.mumirrorb.mapper.GrowthEntryMapper;
import org.xianshen.mumirrorb.pojo.DO.GrowthAxis;
import org.xianshen.mumirrorb.pojo.DO.GrowthEntry;
import org.xianshen.mumirrorb.pojo.DTO.GrowthAdjustmentDTO;
import org.xianshen.mumirrorb.pojo.VO.GrowthOverviewVO;
import org.xianshen.mumirrorb.service.GrowthService;
import java.time.OffsetDateTime;
import java.util.*;
import java.util.stream.Collectors;

@Service @RequiredArgsConstructor
public class GrowthServiceImpl implements GrowthService {
 private final GrowthAxisMapper axesMapper; private final GrowthEntryMapper entriesMapper; private final GrowthProperties properties;
 @org.springframework.beans.factory.annotation.Autowired private org.springframework.jdbc.core.JdbcTemplate jdbc;
 @Override @Transactional public List<GrowthAxis> axes(UUID userId){
  List<GrowthAxis> found=axesMapper.selectList(new LambdaQueryWrapper<GrowthAxis>().eq(GrowthAxis::getUserId,userId));
  if(found==null)found=new ArrayList<>();
  if(found.isEmpty()){ for(var d:properties.getDefaults()){var a=new GrowthAxis();a.setUserId(userId);a.setDimensionId(d.getId());a.setName(d.getName());a.setDescription(d.getDescription());a.setDefinitionVersion(1L);a.setUpdatedAt(OffsetDateTime.now());axesMapper.insert(a);found.add(a);if(jdbc!=null)jdbc.update("INSERT INTO growth_axis_history(user_id,dimension_id,definition_version,name,description) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING",userId,d.getId(),1,d.getName(),d.getDescription());} }
  if(found.size()!=5) throw new BusinessException(409,"成长维度定义无效"); return found;
 }
 @Override public long axesVersion(UUID userId){return axes(userId).stream().mapToLong(a->a.getDefinitionVersion()==null?1:a.getDefinitionVersion()).max().orElse(1);}
 @Override @Transactional public GrowthOverviewVO overview(UUID userId){List<GrowthAxis> axes=axes(userId);List<GrowthEntry> rows=entriesMapper.selectList(new LambdaQueryWrapper<GrowthEntry>().eq(GrowthEntry::getUserId,userId).orderByDesc(GrowthEntry::getCreatedAt));Map<String,Long> totals=rows.stream().collect(Collectors.groupingBy(GrowthEntry::getDimensionId,Collectors.summingLong(e->e.getPoints()==null?0:e.getPoints())));var out=new GrowthOverviewVO();out.setThresholds(properties.getStages());var cfg=new GrowthOverviewVO.Config();cfg.setAiSuggestionMin(0);cfg.setAiSuggestionMax(properties.getAiMaxPoints());cfg.setReviewMin(0);cfg.setReviewMax(properties.getManualMaxPoints());cfg.setManualMin(0);cfg.setManualMax(properties.getManualMaxPoints());cfg.setThresholds(properties.getStages());out.setConfig(cfg);out.setAxesVersion(axesVersion(userId));out.setTotalPoints(totals.values().stream().mapToLong(Long::longValue).sum());var stage=new GrowthOverviewVO.Stage();int idx=0;for(int i=0;i<properties.getStages().size();i++)if(out.getTotalPoints()>=properties.getStages().get(i))idx=i;stage.setIndex(idx);stage.setLabel(List.of("萌芽","积累","进阶","稳步","丰盛").get(Math.min(idx,4)));stage.setThreshold(properties.getStages().get(idx));out.setStage(stage);for(var a:axes){var v=new GrowthOverviewVO.Axis();v.setId(a.getDimensionId());v.setName(a.getName());v.setDescription(a.getDescription());v.setDefinitionVersion(a.getDefinitionVersion());v.setTotalPoints(totals.getOrDefault(a.getDimensionId(),0L));int s=0;for(int i=0;i<properties.getStages().size();i++)if(v.getTotalPoints()>=properties.getStages().get(i))s=i;v.setStageIndex(s);out.getAxes().add(v);}for(var e:rows.stream().limit(20).toList())out.getRecentEntries().add(entryVO(userId,e,axes));return out;}
 @Override @Transactional public GrowthOverviewVO adjustManual(UUID userId,GrowthAdjustmentDTO dto){if(dto.getRequestId()==null)throw new BusinessException(400,"requestId 必填以保证重试幂等");axes(userId);var old=entriesMapper.selectOne(new LambdaQueryWrapper<GrowthEntry>().eq(GrowthEntry::getUserId,userId).eq(GrowthEntry::getActionId,dto.getRequestId()));if(old!=null)return overview(userId);validateAxis(userId,dto.getDimensionId());if(dto.getEntryId()!=null){var entry=entriesMapper.selectOne(new LambdaQueryWrapper<GrowthEntry>().eq(GrowthEntry::getId,dto.getEntryId()).eq(GrowthEntry::getUserId,userId));if(entry==null)throw new BusinessException(404,"成长条目不存在");if(!Objects.equals(entry.getVersion(),dto.getExpectedVersion()))throw new BusinessException(409,"成长条目已变化，请刷新");if(jdbc!=null)jdbc.update("INSERT INTO growth_entry_history(entry_id,user_id,dimension_id,points,reason,definition_version,entry_version,replacement_request_id) VALUES(?,?,?,?,?,?,?,?)",entry.getId(),userId,entry.getDimensionId(),entry.getPoints(),entry.getReason(),entry.getDefinitionVersion(),entry.getVersion(),dto.getRequestId());entry.setDimensionId(dto.getDimensionId());entry.setPoints(dto.getPoints());entry.setReason(dto.getReason());entry.setVersion(entry.getVersion()+1);entriesMapper.updateById(entry);}else{var e=new GrowthEntry();e.setUserId(userId);e.setDimensionId(dto.getDimensionId());e.setPoints(dto.getPoints());e.setReason(dto.getReason());e.setDefinitionVersion(axis(userId,dto.getDimensionId()).getDefinitionVersion());e.setSourceType("manual");e.setActionId(dto.getRequestId());e.setVersion(1L);e.setCreatedAt(OffsetDateTime.now());entriesMapper.insert(e);}return overview(userId);}
 @Override @Transactional public void applyConfirmedRecord(UUID userId,Long recordId,UUID actionId,List<GrowthAdjustmentDTO> suggestions,long expectedAxesVersion){if(axesVersion(userId)!=expectedAxesVersion)throw new BusinessException(409,"成长维度已变化，请重新审核建议");for(var d:suggestions){if(d.getPoints()==null||d.getPoints()<0||d.getPoints()>properties.getManualMaxPoints())throw new BusinessException(400,"AI 成长建议分数越界");validateAxis(userId,d.getDimensionId());var exists=entriesMapper.selectOne(new LambdaQueryWrapper<GrowthEntry>().eq(GrowthEntry::getUserId,userId).eq(GrowthEntry::getSourceRecordId,recordId).eq(GrowthEntry::getDimensionId,d.getDimensionId()));if(exists!=null)continue;var e=new GrowthEntry();e.setUserId(userId);e.setDimensionId(d.getDimensionId());e.setPoints(d.getPoints());e.setReason(d.getReason());e.setDefinitionVersion(axis(userId,d.getDimensionId()).getDefinitionVersion());e.setSourceType("record");e.setSourceRecordId(recordId);e.setActionId(actionId);e.setVersion(1L);e.setCreatedAt(OffsetDateTime.now());entriesMapper.insert(e);}}
 @Override public List<?> entries(UUID userId){var axes=axes(userId);return entriesMapper.selectList(new LambdaQueryWrapper<GrowthEntry>().eq(GrowthEntry::getUserId,userId).orderByDesc(GrowthEntry::getCreatedAt)).stream().map(e->entryVO(userId,e,axes)).toList();}
 private GrowthOverviewVO.Entry entryVO(UUID userId,GrowthEntry e,List<GrowthAxis> axes){var v=new GrowthOverviewVO.Entry();v.setId(e.getId());v.setDimensionId(e.getDimensionId());v.setDefinitionVersion(e.getDefinitionVersion());v.setPoints(e.getPoints());v.setReason(e.getReason());v.setSourceType(e.getSourceType());v.setSourceRecordId(e.getSourceRecordId());v.setVersion(e.getVersion());v.setCreatedAt(e.getCreatedAt()==null?null:e.getCreatedAt().toString());GrowthAxis current=axes.stream().filter(a->a.getDimensionId().equals(e.getDimensionId())).findFirst().orElse(null);if(jdbc!=null){try{var hist=jdbc.queryForMap("SELECT name,description FROM growth_axis_history WHERE user_id=? AND dimension_id=? AND definition_version=?",userId,e.getDimensionId(),e.getDefinitionVersion());v.setAxisName(String.valueOf(hist.get("name")));v.setAxisDescription(String.valueOf(hist.get("description")));}catch(Exception ignored){}}if(v.getAxisName()==null&&current!=null){v.setAxisName(current.getName());v.setAxisDescription(current.getDescription());}return v;}
 @Override @Transactional public List<GrowthAxis> updateAxes(UUID userId,long expectedVersion,List<GrowthProperties.Axis> values){var current=axes(userId);if(axesVersion(userId)!=expectedVersion)throw new BusinessException(409,"成长维度已变化，请刷新");if(values==null||values.size()!=5||values.stream().map(GrowthProperties.Axis::getId).distinct().count()!=5||!values.stream().map(GrowthProperties.Axis::getId).collect(Collectors.toSet()).equals(current.stream().map(GrowthAxis::getDimensionId).collect(Collectors.toSet())))throw new BusinessException(400,"必须保留恰好五个维度槽位");for(var v:values){if(v.getName()==null||v.getName().isBlank()||v.getName().length()>80||v.getDescription()==null)throw new BusinessException(400,"维度名称或说明无效");var a=current.stream().filter(x->x.getDimensionId().equals(v.getId())).findFirst().orElseThrow();if(jdbc!=null)jdbc.update("INSERT INTO growth_axis_history(user_id,dimension_id,definition_version,name,description) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING",userId,a.getDimensionId(),a.getDefinitionVersion(),a.getName(),a.getDescription());a.setName(v.getName().trim());a.setDescription(v.getDescription());a.setDefinitionVersion(a.getDefinitionVersion()+1);a.setUpdatedAt(OffsetDateTime.now());axesMapper.updateById(a);if(jdbc!=null)jdbc.update("INSERT INTO growth_axis_history(user_id,dimension_id,definition_version,name,description) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING",userId,a.getDimensionId(),a.getDefinitionVersion(),a.getName(),a.getDescription());}return axes(userId);}
 private GrowthAxis axis(UUID userId,String id){return axes(userId).stream().filter(a->a.getDimensionId().equals(id)).findFirst().orElseThrow(()->new BusinessException(400,"未知成长维度"));}
 private void validateAxis(UUID userId,String id){axis(userId,id);}
}
